import torch
import torch.nn as nn


class MLP(nn.Module):

    def __init__(
        self,
        input_size,
        hidden_size,
        output_size,
        num_hidden_layers=2,
        dropout_rate=0.1
    ):

        super().__init__()

        layers = []

        in_features = input_size

        for _ in range(num_hidden_layers):

            layers.append(
                nn.Linear(
                    in_features,
                    hidden_size
                )
            )

            layers.append(nn.ReLU())

            layers.append(
                nn.Dropout(dropout_rate)
            )

            in_features = hidden_size

        layers.append(
            nn.Linear(
                in_features,
                output_size
            )
        )

        self.network = nn.Sequential(
            *layers
        )

    def forward(self, x):

        return self.network(x)

